public class Playlist
{
    private readonly List<(string Title, int Seconds)> _songs = new();
    private string _name = "";

    public Playlist(string name)
    {
        Name = name;
    }

    public string Name
    {
        get => _name;
        set
        {
            if (string.IsNullOrWhiteSpace(value)) throw new ArgumentException("a playlist needs a name");
            _name = value.Trim();
        }
    }

    public int Count => _songs.Count;

    public int TotalSeconds => _songs.Sum(s => s.Seconds);

    public string Duration
    {
        get
        {
            int t = TotalSeconds;
            int h = t / 3600, m = t % 3600 / 60, s = t % 60;
            return h > 0 ? $"{h}:{m:D2}:{s:D2}" : $"{m}:{s:D2}";
        }
    }

    public IReadOnlyList<string> Titles => _songs.Select(s => s.Title).ToList().AsReadOnly();

    public void Add(string title, int seconds)
    {
        if (string.IsNullOrWhiteSpace(title)) throw new ArgumentException("a song needs a title");
        if (seconds <= 0) throw new ArgumentOutOfRangeException(nameof(seconds), "must be positive");
        _songs.Add((title, seconds));
    }

    public bool Remove(string title)
    {
        int i = _songs.FindIndex(s => string.Equals(s.Title, title, StringComparison.OrdinalIgnoreCase));
        if (i < 0) return false;
        _songs.RemoveAt(i);
        return true;
    }
}

