Test("adding songs", () =>
{
    var p = new Playlist("Road trip");
    p.Add("Africa", 295);
    p.Add("Holiday", 380);
    CheckEq(p.Name, "Road trip");
    CheckEq(p.Count, 2);
    CheckEq(p.TotalSeconds, 675);
    CheckEq(p.Duration, "11:15");
    CheckEq(p.Titles, new[] { "Africa", "Holiday" });
});

Test("long playlists", () =>
{
    var p = new Playlist("Epic");
    p.Add("One", 3600);
    p.Add("Two", 125);
    CheckEq(p.Duration, "1:02:05");
    CheckEq(new Playlist("Empty").Duration, "0:00");
});

Test("names are validated", () =>
{
    var p = new Playlist("x");
    p.Name = "  Summer ";
    CheckEq(p.Name, "Summer");
    CheckThrows<ArgumentException>(() => p.Name = "   ");
    CheckEq(p.Name, "Summer");
    CheckThrows<ArgumentException>(() => new Playlist(""));
});

Test("songs are validated", () =>
{
    var p = new Playlist("x");
    CheckThrows<ArgumentOutOfRangeException>(() => p.Add("Silence", 0));
    CheckThrows<ArgumentException>(() => p.Add(" ", 10));
    CheckEq(p.Count, 0);
});

Test("removing and read-only titles", () =>
{
    var p = new Playlist("x");
    p.Add("Holiday", 380);
    p.Add("Africa", 295);
    p.Add("holiday", 100);
    var before = p.Titles;
    CheckEq(p.Remove("HOLIDAY"), true);
    CheckEq(p.Titles, new[] { "Africa", "holiday" });
    CheckEq(before.Count, 3);
    CheckEq(p.Remove("Nope"), false);
    Check(p.Titles is not List<string>, "Titles should not hand out a List callers can change");
});

